def count_no_of_ways(n, k):
    """Write a function to find out the number of ways of painting the fence such that at most 2 adjacent posts have the same color for the given fence with n posts and k colors."""
    if n <= 0 or k <= 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k

    # For n > 2, a valid painting either ends with a post whose color
    # differs from the previous post, or with exactly two posts of the
    # same (new) color. This gives:
    #   f(n) = (k - 1) * (f(n - 1) + f(n - 2))
    ways_two_back = k  # f(1)
    ways_one_back = k * k  # f(2)
    for _ in range(3, n + 1):
        ways = (k - 1) * (ways_one_back + ways_two_back)
        ways_two_back, ways_one_back = ways_one_back, ways
    return ways_one_back
